import random
import string
import pandas as pd

def task_func(data_list, seed=0):
    rng = random.Random(seed)

    def random_lower_string(length):
        return "".join(rng.choice(string.ascii_lowercase) for _ in range(length))

    original_strings = []
    modified_strings = []

    for s in data_list:
        original_strings.append(s)

        parts = s.split(",")
        if parts:
            idx = rng.randrange(len(parts))
            parts[idx] = random_lower_string(len(parts[idx]))
        modified_strings.append(",".join(parts))

    return pd.DataFrame({
        "Original String": original_strings,
        "Modified String": modified_strings
    })
